using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using SilicaLab.Api.Data.Entities;

namespace SilicaLab.Api.Data.Configurations;

public class AppUserConfiguration : IEntityTypeConfiguration<AppUser>
{
    public void Configure(EntityTypeBuilder<AppUser> builder)
    {
        builder.ToTable("Users");

        // Primary Key (UUIDv7 generated by the application)
        builder.HasKey(u => u.Id);
        builder.Property(u => u.Id)
            .ValueGeneratedNever();

        // Email: varchar(256), unique, required
        builder.Property(u => u.Email)
            .IsRequired()
            .HasMaxLength(256);

        builder.HasIndex(u => u.Email)
            .IsUnique();

        // PasswordHash: text, required
        builder.Property(u => u.PasswordHash)
            .IsRequired()
            .HasColumnType("text");

        // FullName: varchar(50), required
        builder.Property(u => u.FullName)
            .IsRequired()
            .HasMaxLength(50);

        // Role: varchar(20), stored as string, default 'Student'
        builder.Property(u => u.Role)
            .IsRequired()
            .HasMaxLength(20)
            .HasConversion<string>()
            .HasDefaultValue(UserRole.Student);

        // IsActive: bool, default true
        builder.Property(u => u.IsActive)
            .IsRequired()
            .HasDefaultValue(true);

        // FailedLoginAttempts: int, default 0
        builder.Property(u => u.FailedLoginAttempts)
            .IsRequired()
            .HasDefaultValue(0);

        // LockoutEnd: timestamptz null (automatic for DateTimeOffset? in Npgsql)
        builder.Property(u => u.LockoutEnd)
            .IsRequired(false);

        // CreatedAt: timestamptz, required (automatic for DateTimeOffset in Npgsql)
        builder.Property(u => u.CreatedAt)
            .IsRequired();
    }
}